if (!defined('ABSPATH')) exit;

function zp_suite_232_is_about_page(){
  if (is_admin()) return false;
  if (function_exists('is_page') && (is_page('o-nas') || is_page('onas') || is_page('about'))) return true;
  if (function_exists('is_singular') && is_singular()) {
    $post_id = get_queried_object_id();
    $content = $post_id ? (string) get_post_field('post_content', $post_id) : '';
    if ($content && (has_shortcode($content, 'zp_o_nas') || has_shortcode($content, 'zp_page_o_nas') || has_shortcode($content, 'zp_about_page'))) return true;
  }
  return false;
}

add_filter('body_class', function($classes){
  if (!zp_suite_232_is_about_page()) return $classes;
  foreach (['zp-about-page-light-nav','zp-realizacje-page','zp-realizacje-shortcode'] as $c) {
    if (!in_array($c, $classes, true)) $classes[] = $c;
  }
  return $classes;
}, 2147483647);

